create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','admin');
create type public.order_status as enum ('pending','processing','shipped','delivered','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', email text not null unique, phone text, role public.app_role not null default 'customer', created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(), name text not null unique, description text, created_at timestamptz not null default now());
create table public.brands(id uuid primary key default gen_random_uuid(), name text not null unique, logo_url text);
create table public.products(id uuid primary key default gen_random_uuid(), name text not null, description text not null default '', price numeric(12,2) not null check(price>=0), stock integer not null default 0 check(stock>=0), category_id uuid references public.categories(id), brand_id uuid references public.brands(id), image_url text, specifications jsonb not null default '{}', created_at timestamptz not null default now());
create table public.carts(id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, created_at timestamptz not null default now());
create table public.cart_items(id uuid primary key default gen_random_uuid(), cart_id uuid not null references public.carts(id) on delete cascade, product_id uuid not null references public.products(id), quantity integer not null check(quantity>0), unique(cart_id,product_id));
create table public.orders(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), total_amount numeric(12,2) not null check(total_amount>=0), status public.order_status not null default 'pending', payment_status text not null default 'pending' check(payment_status in ('pending','paid','failed','demo_pending','demo_paid')), shipping_address jsonb not null, created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), product_name text not null, quantity integer not null check(quantity>0), unit_price numeric(12,2) not null check(unit_price>=0));
create table public.payments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, amount numeric(12,2) not null check(amount>=0), payment_method text not null, payment_status text not null default 'pending', transaction_id text, created_at timestamptz not null default now());
create index products_category_idx on public.products(category_id); create index products_brand_idx on public.products(brand_id); create index orders_user_idx on public.orders(user_id); create index order_items_order_idx on public.order_items(order_id); create index payments_order_idx on public.payments(order_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
do $$ declare t text; begin foreach t in array array['profiles','categories','brands','products','carts','cart_items','orders','order_items','payments'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "profiles view own or admin" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "profiles update own" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid() and role='customer');
create policy "categories public read" on public.categories for select using(true); create policy "categories admin manage" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "brands public read" on public.brands for select using(true); create policy "brands admin manage" on public.brands for all using(public.is_admin()) with check(public.is_admin());
create policy "products public read" on public.products for select using(true); create policy "products admin manage" on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy "carts owner access" on public.carts for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "cart items own cart" on public.cart_items for all using(exists(select 1 from public.carts c where c.id=cart_id and (c.user_id=auth.uid() or public.is_admin()))) with check(exists(select 1 from public.carts c where c.id=cart_id and (c.user_id=auth.uid() or public.is_admin())));
create policy "orders owner read" on public.orders for select using(user_id=auth.uid() or public.is_admin()); create policy "orders owner create" on public.orders for insert with check(user_id=auth.uid()); create policy "orders admin update" on public.orders for update using(public.is_admin()) with check(public.is_admin());
create policy "order items related read" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin())));
create policy "order items owner insert" on public.order_items for insert with check(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "payments related read" on public.payments for select using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin())));
create policy "payments owner create" on public.payments for insert with check(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid())); create policy "payments admin update" on public.payments for update using(public.is_admin()) with check(public.is_admin());
